def health(self) -> dict[str, Any]:
        if self.in_process:
            return {"live": True, "mode": "in_process"}
        status = self.status()
        return {
            "live": bool(status.get("up") and status.get("ready")),
            "mode": "detached",
            **({"pid": status["pid"]} if status.get("pid") else {}),
            **({"backend": status["backend"]} if "backend" in status else {}),
        }

